path = pathlib.Path("src/p_lx_elf.cpp")
s = path.read_text(encoding="utf-8", errors="replace")

def replace_block(func_name, replacement):
    global s
    # match function body up to the gashtab block (which must remain)
    pat = re.compile(rf"({re.escape(func_name)}\\(char const \\*name\\) const\\n\\{{)"  # signature+{
                     r"(?P<body>.*?)"  # body
                     r"(\\n\\s*if \\(gashtab && dynsym && dynstr\\) \\{)",
                     re.S)
    m = pat.search(s)
    if not m:
        raise SystemExit(f"cannot locate {func_name} block")
    body = m.group('body')
    # find the first sysv hash block
    subpat = re.compile(r"\\n\\s*if \\(hashtab && dynsym && dynstr\\) \\{.*?\\n\\s*\\}\\n", re.S)
    subm = subpat.search(body)
    if not subm:
        raise SystemExit(f"cannot find hashtab block in {func_name}")
    new_body = body[:subm.start()] + "\n" + replacement + "\n" + body[subm.end():]
    s = s[:m.start('body')] + new_body + s[m.end('body'):]

