def replace_sysv(func_name: str, end_comment: str):
    global s
    # locate function
    m = re.search(rf"{re.escape(func_name)}\(char const \*name\) const\n\{{", s)
    if not m:
        raise SystemExit(f"not found: {func_name}")
    start = m.start()
    # find matching brace for function
    brace = s.find("{", m.end()-1)
    depth = 0
    i = brace
    while i < len(s):
        if s[i] == '{':
            depth += 1
        elif s[i] == '}':
            depth -= 1
            if depth == 0:
                end = i + 1
                break
        i += 1
    else:
        raise SystemExit("no matching brace")
    func = s[start:end]

    # Replace SysV DT_HASH block (the one that begins with if (hashtab...) and ends right before if (gashtab...)
    pat = re.compile(r"\n\s*if \(hashtab && dynsym && dynstr\) \{.*?\n\s*\}\n\s*if \(gashtab && dynsym && dynstr\) \{", re.S)
    mm = pat.search(func)
    if not mm:
        raise SystemExit(f"sysv block not found in {func_name}")

    sysv = f"""
    if (hashtab && dynsym && dynstr) {{
        // SysV DT_HASH layout: u32 nbucket; u32 nchain; u32 bucket[nbucket]; u32 chain[nchain]
        // Guard against malformed DT_HASH that could cause out-of-bounds reads while walking chains.
        unsigned const n_bucket = get_te32(&hashtab[0]);
        unsigned const n_chain  = get_te32(&hashtab[1]);
        unsigned const *const buckets = &hashtab[2];

        // Best-effort end pointers.
        void const *l_hash = nullptr, *l_sym = nullptr;
        for (unsigned j = 0; j < DT_NUM; ++j) {{
            void const *const ptr = dt_offsets[j] + (char const *)file_image.getVoidPtr();
            if (!l_hash && hashtab == ptr) {{
                l_hash = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
            }}
            if (!l_sym && dynsym == ptr) {{
                l_sym = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
            }}
            if (l_sym && l_hash)
                break;  // found both
            if (this->file_size == (off_t)dt_offsets[j])
                break;{end_comment}
        }}

        // Derive a safe chain bound from the actual DT_HASH memory range.
        void const *hash_limit_v = (void const *)hashend;
        if (!hash_limit_v) hash_limit_v = l_hash;
        if (!hash_limit_v) hash_limit_v = (char const *)file_image.getVoidPtr() + file_size;

        unsigned chain_limit = 0;
        if (hash_limit_v) {{
            char const *const buckets_bytes = (char const *)(void const *)buckets;
            char const *const limit_bytes   = (char const *)hash_limit_v;
            if (limit_bytes > buckets_bytes) {{
                unsigned const n_words = (unsigned)((limit_bytes - buckets_bytes) / sizeof(*buckets));
                if (n_words >= n_bucket) {{
                    unsigned const max_chain = n_words - n_bucket;
                    chain_limit = (n_chain < max_chain) ? n_chain : max_chain;
                }}
            }}
        }}

        if (n_bucket && chain_limit) {{
            unsigned const *const chains = &buckets[n_bucket];
            unsigned const m = elf_hash(name) % n_bucket;
            unsigned n_visit = 0;
            for (unsigned si = get_te32(&buckets[m]); si && n_visit++ < chain_limit; ) {{
                if (si >= chain_limit)
                    break;
                if (symnum_max && si >= symnum_max)
                    break;
                if (l_sym && l_sym <= &dynsym[si])
                    break;
                char const *const p = get_dynsym_name(si, (unsigned)-1);
                if (p && 0==strcmp(name, p))
                    return &dynsym[si];
                si = get_te32(&chains[si]);
            }}
        }}
    }}
    if (gashtab && dynsym && dynstr) {{"""

    func2 = func[:mm.start()] + sysv + func[mm.end():]
