    unsigned char ei_class;
    unsigned char ei_data;
    unsigned char ei_osabi;
    unsigned char prev_method;
    char const *osabi_note;
    unsigned upx_dt_init;  // DT_INIT, DT_PREINIT_ARRAY, DT_INIT_ARRAY
