from pathlib import Path
import re

path = Path("src/p_lx_elf.cpp")
s = path.read_text(encoding="utf-8", errors="replace")


def find_matching_brace(txt: str, open_brace_index: int) -> int:
    depth = 0
    for i in range(open_brace_index, len(txt)):
        c = txt[i]
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i
    raise ValueError("no matching brace")


def replace_sysv_block(func_sig: str, end_comment: str):
    global s
    m = re.search(re.escape(func_sig) + r"\n\{", s)
    if not m:
        raise SystemExit(f"function signature not found: {func_sig}")
    func_start = m.start()
    open_brace = s.find('{', m.end()-1)
    func_end_brace = find_matching_brace(s, open_brace)
    func_end = func_end_brace + 1
    func = s[func_start:func_end]

    key = "if (hashtab && dynsym && dynstr) {"
    k = func.find(key)
    if k < 0:
        raise SystemExit(f"sysv if not found in {func_sig}")
    sysv_open = func.find('{', k)
    sysv_close = find_matching_brace(func, sysv_open)
    old_block = func[k:sysv_close+1]

    new_block = f'''if (hashtab && dynsym && dynstr) {{
        // SysV DT_HASH layout: u32 nbucket; u32 nchain; u32 bucket[nbucket]; u32 chain[nchain]
        // Guard against malformed DT_HASH that could cause out-of-bounds reads while walking chains.
        unsigned const nbucket_sysv = get_te32(&hashtab[0]);
        unsigned const nchain_sysv  = get_te32(&hashtab[1]);
        unsigned const *const buckets_sysv = &hashtab[2];
        unsigned const *chains_sysv = nullptr;

        // Find the end of DT_HASH and DT_DYNSYM (best effort).
        void const *l_hash = nullptr, *l_sym = nullptr;
        for (unsigned j = 0; j < DT_NUM; ++j) {{
            void const *const ptr = dt_offsets[j] + (char const *)file_image.getVoidPtr();
            if (!l_hash && hashtab == ptr) {{
                l_hash = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
            }}
            if (!l_sym && dynsym == ptr) {{
                l_sym = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
            }}
            if (l_sym && l_hash)
                break;  // found both
            if (this->file_size == (off_t)dt_offsets[j])
                break;{end_comment}
        }}

        // Compute and validate available DT_HASH words.
        unsigned const *hash_limit = hashend;
        if (!hash_limit) hash_limit = (unsigned const *)l_hash;
        if (!hash_limit) hash_limit = (unsigned const *)(void const *)((char const *)file_image.getVoidPtr() + file_size);
        if (hash_limit <= buckets_sysv) {{
            throwCantPack("bad DT_HASH");
        }}
        unsigned const n_words = (unsigned)(hash_limit - buckets_sysv);
        if (n_words < nbucket_sysv) {{
            throwCantPack("bad DT_HASH nbucket=%#x", nbucket_sysv);
        }}
        unsigned const max_chain = n_words - nbucket_sysv;
        if (nchain_sysv > max_chain) {{
            throwCantPack("bad DT_HASH nchain=%#x", nchain_sysv);
        }}
        chains_sysv = &buckets_sysv[nbucket_sysv];

        if (nbucket_sysv) {{
            unsigned const m = elf_hash(name) % nbucket_sysv;
            unsigned n_visit = 0;
            unsigned si;
            if (l_hash && l_hash <= &buckets_sysv[m])
                throwCantPack("bad DT_HASH %u", m);
            for (si= get_te32(&buckets_sysv[m]); si; ) {{
                if (si >= nchain_sysv)
                    throwCantPack("bad DT_HASH chain %u\n", si);
                if (symnum_max && si >= symnum_max)
                    throwCantPack("bad DT_HASH sym %u\n", si);
                if (l_sym && l_sym <= &dynsym[si])
                    throwCantPack("bad DT_HASH chain %d\n", si);
                char const *const p = get_dynsym_name(si, (unsigned)-1);
                if (p && 0==strcmp(name, p))
                    return &dynsym[si];
                if (++n_visit > nchain_sysv)
                    throwCantPack("circular DT_HASH chain %d\n", si);
                si = get_te32(&chains_sysv[si]);
            }}
        }}
    }}'''

    func2 = func.replace(old_block, new_block, 1)
    s = s[:func_start] + func2 + s[func_end:]


replace_sysv_block("Elf32_Sym const *PackLinuxElf32::elf_lookup(char const *name) const", "  // end sentinel")
replace_sysv_block("Elf64_Sym const *PackLinuxElf64::elf_lookup(char const *name) const", "  //end")

path.write_text(s, encoding="utf-8")
print("patched sysv blocks")
PY

