    unsigned e_type;
    unsigned e_phnum;       /* Program header table entry count */
    unsigned e_shnum;
    unsigned e_shstrndx;
    MemBuffer file_image;   // if ET_DYN investigation
    MemBuffer lowmem;  // at least including PT_LOAD[0]
