# Helper to replace the first sysv hashtab block inside a given elf_lookup function

def replace_sysv_block(func_name: str, new_block: str):
    global s
    # find function start
    m = re.search(rf"{re.escape(func_name)}\(char const \*name\) const\n\{{", s)
    if not m:
        raise SystemExit(f"function not found: {func_name}")
    start = m.start()
    end = s.find("\n}\n\n", m.end())
    if end < 0:
        raise SystemExit(f"function end not found: {func_name}")
    end += len("\n}\n\n")
    func = s[start:end]

    # replace sysv block (must appear before gashtab block)
    pat = re.compile(r"\n\s*if \(hashtab && dynsym && dynstr\) \{.*?\n\s*\}\n\s*if \(gashtab && dynsym && dynstr\) \{", re.S)
