def find_block(txt: str, start_idx: int) -> tuple[int,int]:
    """Given index pointing at beginning of an if statement, return (start,end_exclusive) covering the whole {...} block."""
    brace = txt.find("{", start_idx)
    if brace < 0:
        raise ValueError("no opening brace")
    depth = 0
    for i in range(brace, len(txt)):
        c = txt[i]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return start_idx, i + 1
    raise ValueError("no matching brace")


